<script setup>
import { reactive,ref } from 'vue';import { ElMessage } from 'element-plus';import { uploadDocument } from '../../api/document';import { messageOf } from '../../utils/request';import PageHeader from '../../components/PageHeader.vue'
const form=reactive({caseId:null,remark:''});const file=ref();const loading=ref(false);const upload=async()=>{if(!file.value)return ElMessage.warning('请选择官文文件');loading.value=true;try{const data=new FormData();data.append('file',file.value);data.append('caseId',form.caseId);data.append('documentType','OFFICIAL');if(form.remark)data.append('remark',form.remark);await uploadDocument(data);ElMessage.success('官文已上传，案件通知已生成');file.value=null;form.remark=''}catch(e){ElMessage.error(messageOf(e))}finally{loading.value=false}}
</script>
<template><div class="page narrow-page"><PageHeader title="官文录入" description="上传真实文件并关联案件，系统将生成阶段和站内通知"/><section class="surface business-form"><el-alert title="上传后可在文件审核页查看；官文日期、期限和费用可通过后端人工 OCR 确认接口补录。" type="info" :closable="false"/><el-form label-position="top"><el-form-item label="关联案件 ID" required><el-input-number v-model="form.caseId" :min="1"/></el-form-item><el-form-item label="选择官文文件" required><input type="file" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png" @change="file=$event.target.files[0]"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item><el-button type="primary" :loading="loading" @click="upload">上传官文</el-button></el-form></section></div></template>
